/**
 *
 * DataTableFilter provides PrimeVue-style filter controls for DataTable columns.
 * Supports both "row" (inline) and "menu" (overlay with multiple constraints) display modes.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableFilter
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableFilterEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
export type DataTableFilterPassThroughType<E> = PassThroughType<DataTableFilterInstance, E>;
export interface DataTableFilterPassThrough {
    root?: DataTableFilterPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Filter display mode.
 * 'row' - Inline filter in the column header, applies immediately.
 * 'menu' - Overlay/popover with multiple constraints, apply/clear buttons, operator selection.
 */
export type DataTableFilterDisplay = 'row' | 'menu';
export interface DataTableFilterProps extends BaseComponentProps<DataTableFilterInstance, unknown, DataTableFilterPassThrough, 'div'> {
    /**
     * The field name to filter.
     */
    field: string;
    /**
     * Display mode of the filter.
     * 'row' renders inline and applies immediately.
     * 'menu' provides overlay with constraints, operators, apply/clear.
     * @default 'row'
     */
    display?: DataTableFilterDisplay;
    /**
     * Whether to show the AND/OR operator selector in menu mode.
     * @default true
     */
    showOperator?: boolean;
    /**
     * Whether to show the match mode dropdown.
     * @default true
     */
    showMatchModes?: boolean;
    /**
     * Whether to show the clear button.
     * @default true
     */
    showClearButton?: boolean;
    /**
     * Whether to show the apply button (menu mode only).
     * @default true
     */
    showApplyButton?: boolean;
    /**
     * Whether to show the "add constraint" button (menu mode only).
     * @default true
     */
    showAddButton?: boolean;
    /**
     * Maximum number of constraints per column (menu mode only).
     * @default 2
     */
    maxConstraints?: number;
    /**
     * Custom match mode options. If not provided, defaults based on dataType.
     */
    matchModeOptions?: DataTableMatchModeOption[];
    /**
     * Data type hint for default match modes.
     * 'text' | 'numeric' | 'date' | 'boolean'
     * @default 'text'
     */
    dataType?: string;
}
/**
 * Option for match mode dropdown.
 */
export interface DataTableMatchModeOption {
    label: string;
    value: string;
}
/**
 * Represents a single filter constraint.
 */
export interface DataTableFilterConstraintModel {
    value: unknown;
    matchMode: string;
}
export interface DataTableFilterState {
}
/**
 * Slot context exposed to the `children` render prop and on the component instance.
 */
export interface DataTableFilterExposes {
    /** The DataTable root instance. */
    datatable: DataTableRootInstance | undefined | null;
    /** The field being filtered. */
    field: string;
    /** Current display mode. */
    display: DataTableFilterDisplay;
    /** Current filter value (first constraint's value). */
    value: unknown;
    /** Current match mode (first constraint's matchMode). */
    matchMode: string;
    /** Current operator ('and' | 'or'). */
    operator: 'and' | 'or';
    /** Array of constraints for this field. */
    constraints: DataTableFilterConstraintModel[];
    /** Whether the field has an active filter. */
    isActive: boolean;
    /** Whether a new constraint can be added (not at max). */
    canAddConstraint: boolean;
    /** Whether constraints can be removed (more than 1). */
    canRemoveConstraint: boolean;
    /** Whether the filter overlay is visible (menu mode). */
    overlayVisible: boolean;
    /** Available match mode options. */
    matchModeOptions: DataTableMatchModeOption[];
    /** Update filter value. In row mode, applies immediately. */
    onChange: (event: React.SyntheticEvent, value: unknown, matchMode?: string) => void;
    /** Clear the field filter. */
    onClear: (event: React.SyntheticEvent) => void;
    /** Change the operator. */
    onOperatorChange: (event: React.SyntheticEvent, operator: 'and' | 'or') => void;
    /** Update a specific constraint by index. */
    onConstraintChange: (event: React.SyntheticEvent, index: number, value: unknown, matchMode?: string) => void;
    /** Change match mode of a specific constraint. */
    onMatchModeChange: (event: React.SyntheticEvent, index: number, matchMode: string) => void;
    /** Add a new constraint. */
    onAddConstraint: (event: React.SyntheticEvent) => void;
    /** Remove a constraint by index. */
    onRemoveConstraint: (event: React.SyntheticEvent, index: number) => void;
    /** Apply filter (menu mode - deferred apply). */
    onApply: (event: React.SyntheticEvent) => void;
    /** Toggle the filter overlay. */
    onToggleOverlay: (event: React.SyntheticEvent) => void;
    /** Show the filter overlay. */
    onShowOverlay: () => void;
    /** Hide the filter overlay. */
    onHideOverlay: () => void;
}
export type DataTableFilterInstance = ComponentInstance<DataTableFilterProps, DataTableFilterState, DataTableFilterExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableFilterEvent`.
 */
export interface DataTableFilterEvent extends UseDataTableFilterEvent {
}
